package com.mukasanches.zapptv.data

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

class ChannelResolverTest {
    @Test
    fun resolvesCommonBrazilianNames() {
        assertEquals("BR_GLOBO", ChannelResolver.canonicalId("Globo HD"))
        assertEquals("BR_SBT", ChannelResolver.canonicalId("SBT 5.1"))
        assertEquals("BR_TV_CULTURA", ChannelResolver.canonicalId("TV Cultura HD"))
        assertEquals("BR_TV_CAMARA", ChannelResolver.canonicalId("TV Câmara"))
    }

    @Test
    fun normalizationRemovesAccentsAndPunctuation() {
        assertEquals("tv camara hd", ChannelResolver.normalize("TV CÂMARA — HD"))
    }

    @Test
    fun unknownChannelRemainsUnmapped() {
        assertNull(ChannelResolver.canonicalId("Canal local desconhecido"))
    }
}

package com.mukasanches.zapptv.data

import com.mukasanches.zapptv.model.Channel
import com.mukasanches.zapptv.model.ChannelSource
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

class MediaLibraryBuilderTest {
    private val news = Channel("1", "10", "News HD", ChannelSource.IPTV, category = "Notícias")
    private val sport = Channel("2", "20", "Sport TV", ChannelSource.IPTV, category = "Esportes")

    @Test fun buildsFavoritesRecentAndCategoriesWithoutMutatingChannels() {
        val library = MediaLibraryBuilder.build(
            channels = listOf(news, sport),
            favoriteIds = setOf("2"),
            recentIds = listOf("1")
        )
        assertEquals(listOf(sport), library.favorites)
        assertEquals(listOf(news), library.recent)
        assertEquals(2, library.categories.size)
        assertEquals(listOf(news, sport), library.live)
    }

    @Test fun searchMatchesNameNumberAndCategory() {
        assertEquals(listOf(news), MediaLibraryBuilder.search(listOf(news, sport), "Notícias"))
        assertEquals(listOf(sport), MediaLibraryBuilder.search(listOf(news, sport), "20"))
        assertTrue(MediaLibraryBuilder.search(listOf(news, sport), "inexistente").isEmpty())
    }
}
